import hikari, lightbulb

plugin = lightbulb.Plugin('feather')

def load(bot):
 bot.add_plugin(plugin)

@plugin.command
@lightbulb.command('feather_client', 'Download Feather Client')
@lightbulb.implements(lightbulb.SlashCommand)
async def feather(ctx: lightbulb.Context) -> None:
 embed = hikari.Embed(title='Feather Client', description='Download Feather Client', colour='F44336')
 embed.add_field('Windows Version', 'Click [**here**](https://feathermc.com/download/windows) to start downloading')
 embed.set_thumbnail('data:image/jpeg;base64,')
 await ctx.respond(embed)

